-- 傾印 wowprime 的資料庫結構
CREATE DATABASE IF NOT EXISTS `wowprime` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci */ /*!80016 DEFAULT ENCRYPTION='N' */;
USE `wowprime`;

-- 傾印  資料表 wowprime.stores 結構
CREATE TABLE IF NOT EXISTS `stores` (
  `store_id` int NOT NULL AUTO_INCREMENT COMMENT '門市ID',
  `brand_id` int DEFAULT NULL COMMENT '對應的品牌ID (外鍵)',
  `store_name` varchar(100) NOT NULL COMMENT '門市分店名 (例如: 台北羅斯福店)',
  `full_name` varchar(150) DEFAULT NULL COMMENT '全名 (例如: 王品牛排 台北羅斯福店)',
  `address` varchar(255) DEFAULT NULL COMMENT '完整地址',
  `city` varchar(20) DEFAULT NULL COMMENT '縣市 (例如: 台北市)',
  `district` varchar(20) DEFAULT NULL COMMENT '鄉鎮市區 (例如: 中正區)',
  `phone` varchar(50) DEFAULT NULL COMMENT '電話',
  `booking_url` text COMMENT '線上預約連結',
  `business_hours` text COMMENT '營業時間',
  `status` varchar(20) DEFAULT '營業中' COMMENT '門市狀態 (營業中/歇業)',
  `price_range` varchar(50) DEFAULT NULL COMMENT 'Google 人均消費區間文字 (例如: NT$400-600)',
  `avg_price` int DEFAULT NULL COMMENT '估算平均人均消費金額 (例如: 500, 方便排序與篩選)',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT '緯度 Lat',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT '經度 Lng',
  `google_rating` decimal(2,1) DEFAULT NULL COMMENT 'Google 評分 (1.0~5.0)',
  `google_review_count` int DEFAULT '0' COMMENT 'Google 評論總數',
  `google_place_id` varchar(100) DEFAULT NULL COMMENT 'Google 地圖獨有 Place ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '建立時間',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '資料更新時間',
  PRIMARY KEY (`store_id`),
  KEY `brand_id` (`brand_id`),
  CONSTRAINT `stores_ibfk_1` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`brand_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=318 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

